-- Structured interview bank: (1) complete 4 incomplete HSE rows, (2) add 6 STAR behavioural questions for each of the 24 roles.
-- Applied 2026-10-15; rows are APPROVED by the owner request (no manual review).

update comp_question_bank set
  question_text = btrim(replace(question_text, '_K', '')),
  key_points = '["شیب دیواره متناسب با نوع زمین تنظیم می‌شود","حفاری V شکل یا پله‌ای برای دیوارهٔ عمودی","بازرسی روزانهٔ ترانشه پیش از ورود افراد","نصب سیستم حفاظتی مناسب مثل شمع‌بندی یا جعبهٔ ترانشه"]'::jsonb,
  excellent_answer_indicators = '["ارزیابی نوع خاک و آب زیرزمینی پیش از انتخاب روش حفاظت","دور نگه داشتن بار و ماشین‌آلات از لبهٔ ترانشه"]'::jsonb,
  common_mistakes = '["ورود افراد به ترانشه بدون بازرسی روزانه","اتکا به ظاهر پایدار خاک بدون ارزیابی فنی"]'::jsonb,
  standard_reference = 'ایمنی حفاری و ترانشه / رویهٔ مجوز حفاری'
where id = '3ae096da-4c04-41da-9b75-dfb89c690f3d';

update comp_question_bank set
  question_text = btrim(replace(question_text, '_K', '')),
  key_points = '["اطلاع فوری به مسئول اجرا و مسئول محوطه","کاهش کنترل‌شدهٔ فشار پیش از هر اقدام","عدم تعمیر تا افت کامل فشار","تعیین محدودهٔ خطر و جلوگیری از ورود افراد غیرمجاز","صدور مجوز کار سرد پیش از تعمیر"]'::jsonb,
  excellent_answer_indicators = '["تأیید صفر بودن انرژی با گیج کالیبره پیش از نزدیک شدن","ثبت حادثهٔ شبه‌حادثه و بررسی علت نشتی"]'::jsonb,
  common_mistakes = '["تلاش برای سفت کردن فلنج زیر فشار","نزدیک شدن افراد به نقطهٔ نشتی بدون تعیین محدودهٔ خطر"]'::jsonb,
  standard_reference = 'رویهٔ تست هیدرواستاتیک و مجوز کار'
where id = '6dad9205-2681-4f67-ae1f-93e8949e4eaa';

update comp_question_bank set
  question_text = btrim(replace(question_text, '_K', '')),
  key_points = '["دور کردن کارگر از محل کار","ممنوعیت ورود بدون آموزش و معرفی HSE","محتوای آموزش: خط‌مشی، آمادگی اضطراری، PTW، PPE و رویه‌ها","ثبت آموزش در سیستم پیش از شروع کار"]'::jsonb,
  excellent_answer_indicators = '["بررسی علت ورود بدون آموزش و اصلاح فرایند پذیرش نیرو","اطلاع به سرپرست مستقیم و پیمانکار برای جلوگیری از تکرار"]'::jsonb,
  common_mistakes = '["اجازهٔ کار تحت نظارت همکار بدون آموزش رسمی","آموزش شفاهی کوتاه و ثبت نکردن آن"]'::jsonb,
  standard_reference = 'رویهٔ معرفی HSE (HSE Induction)'
where id = '9d898e2b-b112-4d6c-b30f-2e3bd0b239c4';

update comp_question_bank set
  question_text = btrim(replace(question_text, '_K', '')),
  key_points = '["خطر اصلی برق‌گرفتگی است","تجهیزات عایق‌بندی‌شده و اتصال زمین صحیح","PPE مناسب مانند دستکش عایق","توقف کار تا بهبود شرایط در صورت لزوم"]'::jsonb,
  excellent_answer_indicators = '["کنترل خشک بودن محل ایستادن جوشکار و سالم بودن کابل‌ها","ارزیابی ریسک پیش از شروع و تعیین حد مجاز رطوبت"]'::jsonb,
  common_mistakes = '["ادامهٔ جوشکاری با کابل آسیب‌دیده در محیط مرطوب","اتکا به دستکش معمولی به‌جای دستکش عایق"]'::jsonb,
  standard_reference = 'ایمنی جوشکاری قوسی / رویهٔ کار با برق'
where id = 'b4c7c36b-f210-44d3-999b-30e4f35199a3';

with roles(job_role, fa, dom) as (values
 ('civil_engineer','مهندس عمران','کنترل بتن‌ریزی، خاک‌ریزی یا نقشه‌های اجرایی'),
 ('civil_supervisor','سرپرست عمران','اجرای فونداسیون، خاکریزی و بتن‌ریزی'),
 ('coating_cp_inspector','بازرس پوشش و حفاظت کاتدی','پوشش سرجوش، بلاست و پتانسیل CP'),
 ('coating_supervisor','سرپرست پوشش','بلاست، پوشش و تعمیر پوشش لوله'),
 ('contract_commercial_manager','مدیر قرارداد و بازرگانی','ادعاها، تغییرات و صورت‌وضعیت‌ها'),
 ('contracts_specialist','کارشناس قراردادها','تحلیل ادعا، دستور تغییر و مکاتبات قراردادی'),
 ('goods_materials_inspector','بازرس کالا و مواد','بازرسی ورودی، گواهی MTC و انبار'),
 ('hse_specialist','کارشناس HSE','مجوز کار، ممیزی ایمنی و گزارش حوادث'),
 ('inspection_body_supervisor','سرپرست دستگاه نظارت','ITP، NCR و نظارت بر پیمانکار'),
 ('mechanical_piping_inspector','بازرس لوله‌کشی مکانیکی','تست فشار، فلنج و واکداون'),
 ('mechanical_piping_supervisor','سرپرست لوله‌کشی مکانیکی','نصب اسپول، فلنج و آزمون'),
 ('pipeline_inspector','بازرس خط لوله','ریسه، پایین‌گذاری و تست هیدرواستاتیک'),
 ('pipeline_supervisor','سرپرست خط لوله','ریسه، جوش، پایین‌گذاری و خاکریزی'),
 ('planning_engineer','مهندس برنامه‌ریزی','به‌روزرسانی برنامه، مسیر بحرانی و گزارش پیشرفت'),
 ('project_control_manager','مدیر کنترل پروژه','EVM، پیش‌بینی هزینه و گزارش‌دهی به مدیریت'),
 ('project_control_specialist','کارشناس کنترل پروژه','اندازه‌گیری پیشرفت و تحلیل انحراف'),
 ('project_director','مدیر ارشد پروژه','تصمیم‌های راهبردی، ذی‌نفعان و منابع'),
 ('project_manager','مدیر پروژه','برنامه، هزینه و هماهنگی تیم'),
 ('radiography_interpreter','مفسر رادیوگرافی','تفسیر فیلم و تصمیم قبول یا رد جوش'),
 ('site_supervisor','سرپرست کارگاه','هماهنگی جبهه‌ها و رعایت ایمنی کارگاه'),
 ('supervision_manager','مدیر نظارت','نظارت چندپیمانکاره و استقلال گزارش‌دهی'),
 ('survey_inspector','بازرس نقشه‌برداری','کنترل مختصات، as-built و کالیبراسیون'),
 ('welding_inspector','بازرس جوش','بازرسی چشمی، قبول یا رد جوش و WPS'),
 ('welding_supervisor','سرپرست جوشکاری','WPS، صلاحیت جوشکار و تعمیر جوش')
), comp(sub_category, q, ref, kp, ex, cm) as (values
 ('مسئولیت‌پذیری زیر فشار تحویل',
  'تجربه‌ای را از کار به‌عنوان {role} تعریف کنید که برای تحویل به‌موقع (مثلاً در حوزهٔ {dom}) تحت فشار شدید بودید و باید بین سرعت و الزامات کیفیت یا ایمنی تصمیم می‌گرفتید. موقعیت چه بود، شما دقیقاً چه کردید و نتیجه چه شد؟',
  'پاسخ قوی ساختار STAR دارد: موقعیت و فشار مشخص، وظیفه و اختیار خود فرد، اقدام‌هایی که خودش انجام داده (نه فقط «ما») و نتیجهٔ قابل سنجش. نشان می‌دهد کیفیت یا ایمنی را فدای برنامه نکرده، گزینه‌های جایگزین مثل تفکیک بخش مشکل‌دار، درخواست زمان یا اطلاع به مدیریت را سنجیده و تصمیم را مستند کرده است. از نتیجه درس گرفته و رویهٔ بعدی را بهتر کرده است.',
  '["موقعیت و فشار مشخص و واقعی بیان می‌شود","نقش و اختیار شخصی در تصمیم روشن است","اقدام‌ها با زبان «من» توضیح داده می‌شود","کیفیت یا ایمنی فدای برنامه نشده است","نتیجه و درس‌آموخته بیان می‌شود"]',
  '["گزینه‌های جایگزین را سنجیده و دلیل انتخاب را می‌گوید","نتیجه را با مدرک یا عدد پشتیبانی می‌کند","بعداً رویه یا چک‌لیست را اصلاح کرده است"]',
  '["مثال کلی و فرضی به‌جای تجربهٔ واقعی","نقش خود را از نقش تیم جدا نمی‌کند","قربانی شدن کیفیت را موفقیت می‌داند"]'),
 ('گزارش خبر بد و صداقت حرفه‌ای',
  'زمانی را شرح دهید که به‌عنوان {role} متوجه مشکل یا خطایی (مثلاً در حوزهٔ {dom}) شدید که گزارش آن برای شما یا پروژه ناخوشایند بود. چه زمانی، چگونه و به چه کسی گزارش دادید و پیامد آن چه شد؟',
  'پاسخ قوی نشان می‌دهد فرد مشکل را زود، کامل و مستند گزارش کرده، از پنهان‌کاری یا نرم‌کردن عدد پرهیز کرده و همراه گزارش، علت و پیشنهاد اصلاح داده است. گزارش را به مرجع درست رسانده و پیامد (حتی منفی) را پذیرفته است. از ایجاد اعتماد بلندمدت با مدیریت صحبت می‌کند.',
  '["مشکل مشخص و واقعی توصیف می‌شود","گزارش زودهنگام و کامل بوده است","به مرجع درست و با مستندات ارائه شده است","علت و پیشنهاد اصلاح همراه گزارش آمده است","پیامد بیان و پذیرفته می‌شود"]',
  '["پیش از گزارش، داده را راستی‌آزمایی کرده است","از نرم‌کردن یا پنهان‌کردن عدد پرهیز کرده است","پس از گزارش، پیگیری اقدام اصلاحی را ادامه داده است"]',
  '["تأخیر در گزارش به امید حل مشکل","گزارش ناقص که بخش ناخوشایند را حذف می‌کند","گزارش شفاهی بدون ثبت و مستند"]'),
 ('مدیریت اختلاف با پیمانکار یا همکار',
  'یک اختلاف نظر فنی یا اجرایی جدی (مثلاً در حوزهٔ {dom}) را با پیمانکار یا همکار خود به‌عنوان {role} به یاد بیاورید. موضوع اختلاف چه بود، چگونه رفتار کردید و اختلاف چگونه پایان یافت؟',
  'پاسخ قوی نشان می‌دهد فرد اختلاف را با استناد به معیار مکتوب (کد، مشخصات، قرارداد) و شواهد پیش برده، به طرف مقابل گوش داده، لحن حرفه‌ای را حفظ کرده و در صورت نرسیدن به توافق از مسیر رسمی ارجاع و ثبت استفاده کرده است. رابطه را بدون تسلیم در برابر الزامات حفظ کرده است.',
  '["موضوع اختلاف روشن و فنی است","استناد به معیار مکتوب و شواهد","گوش دادن به طرف مقابل و حفظ لحن حرفه‌ای","ارجاع رسمی در صورت ادامهٔ اختلاف","نتیجه و رابطهٔ بعدی بیان می‌شود"]',
  '["راه‌حل برد-برد بدون عدول از الزامات پیدا کرده است","تصمیم را ثبت کرده و ابلاغ کرده است"]',
  '["تسلیم شدن برای پایان دادن به تنش","تحمیل نظر شخصی بدون استناد","شخصی‌سازی اختلاف و گفتن از «بد بودن» طرف مقابل"]'),
 ('یادگیری از خطای خود',
  'از اشتباه یا قضاوت نادرستی که خودتان در نقش {role} (مثلاً در حوزهٔ {dom}) مرتکب شدید بگویید. چه شد، چه آسیبی داشت و پس از آن چه چیزی را عوض کردید؟',
  'پاسخ قوی مسئولیت اشتباه را بدون فرافکنی می‌پذیرد، پیامد واقعی را توضیح می‌دهد، علت ریشه‌ای را (نه فقط ظاهر) می‌شناسد و تغییر مشخصی در رفتار یا فرایند ایجاد می‌کند. اطلاع‌رسانی به‌موقع و جبران خسارت را شامل می‌شود.',
  '["اشتباه مشخص و واقعی است","مسئولیت بدون فرافکنی پذیرفته می‌شود","پیامد و علت ریشه‌ای بیان می‌شود","تغییر عملی بعد از آن توضیح داده می‌شود"]',
  '["تغییر را با چک‌لیست یا آموزش به دیگران هم منتقل کرده است","اطلاع‌رسانی به‌موقع به ذی‌نفعان داشته است"]',
  '["اشتباه ناچیز یا غیرواقعی انتخاب می‌کند","مقصر دانستن شرایط یا دیگران","درس‌آموخته کلی بدون تغییر قابل مشاهده"]'),
 ('شجاعت توقف کار برای ایمنی یا کیفیت',
  'موردی را تعریف کنید که به‌عنوان {role} لازم بود برای حفظ ایمنی یا کیفیت (مثلاً در حوزهٔ {dom}) کار را متوقف کنید یا مخالفت کنید، در حالی که فشار برای ادامه وجود داشت. چه کردید و چه شد؟',
  'پاسخ قوی نشان می‌دهد فرد خطر یا نقص را با معیار مشخص شناسایی کرده، اختیار توقف را به‌کار گرفته، دلیل را شفاف و مستند به مسئولان اعلام کرده، راه‌حل جایگزین پیشنهاد داده و پس از رفع مشکل کار را از سر گرفته است. فشار را بدون تسلیم یا درگیری غیرحرفه‌ای مدیریت کرده است.',
  '["خطر یا نقص با معیار مشخص بیان می‌شود","از اختیار توقف استفاده شده است","دلیل شفاف و مستند اعلام شده است","راه‌حل جایگزین یا شرایط شروع مجدد روشن است","فشار بدون تسلیم مدیریت شده است"]',
  '["هزینهٔ توقف را سنجیده و با ذی‌نفعان گفتگو کرده است","پس از آن رویه را برای پیشگیری از تکرار اصلاح کرده است"]',
  '["توقف بدون توضیح و مستندسازی","ادامهٔ کار با نگرانی و ثبت نکردن","توقف مبتنی بر سلیقه نه معیار"]'),
 ('تأثیرگذاری بدون اختیار رسمی و هماهنگی بین‌تیمی',
  'موقعیتی را شرح دهید که به‌عنوان {role} برای رسیدن به نتیجه (مثلاً در حوزهٔ {dom}) باید گروه‌ها یا افرادی را که زیر نظر شما نبودند هماهنگ می‌کردید. چگونه آن‌ها را همراه کردید و حاصل چه بود؟',
  'پاسخ قوی نشان می‌دهد فرد منافع و محدودیت‌های طرف‌های دیگر را شناخته، هدف مشترک و داده را مطرح کرده، قدم‌به‌قدم توافق گرفته، نقش‌ها و موعدها را شفاف کرده و پیگیری منظم داشته است. به‌جای اتکا به قدرت رسمی، اعتبار فنی و ارتباط محترمانه را به‌کار می‌گیرد.',
  '["طرف‌های ذی‌نفع و منافع آن‌ها شناسایی می‌شود","هدف مشترک و داده مطرح می‌شود","نقش‌ها و موعدها شفاف می‌شود","پیگیری منظم انجام شده است","نتیجهٔ مشخص بیان می‌شود"]',
  '["از اعتبار فنی و رابطهٔ محترمانه به‌جای فشار استفاده کرده است","نتیجه را در قالب دستاورد مشترک به همه بازخورد داده است"]',
  '["اتکا به دستور مدیر بالاتر به‌جای متقاعدسازی","نادیده گرفتن منافع طرف‌های دیگر","پاسخ کلی بدون مثال مشخص"]')
)
insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, image_url, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference, score_min, score_max, evaluator_note_required, active, weight, approval_status, version, usage_count, proposal_reason)
select r.job_role, 'BEHAVIORAL', c.sub_category, 'L3',
  replace(replace(c.q, '{role}', r.fa), '{dom}', r.dom), '',
  c.ref, c.kp::jsonb, c.ex::jsonb, c.cm::jsonb, 'مصاحبهٔ رفتاری ساختاریافته (STAR)', 0, 5, true, true, 1, 'APPROVED', 1, 0, ''
from roles r cross join comp c
where not exists (select 1 from comp_question_bank b where b.job_role = r.job_role and b.category = 'BEHAVIORAL' and b.sub_category = c.sub_category);
